/*
 * NOTE: :not() works around interference from the skin on mobile.
 *
 * All size classes get overridden on mobile by a high-specificity selector on
 * the p element. This means font size templates do not really work on mobile
 * and p-wrapping can lead to really inconsistent results. We need to exceed a
 * specificity of 0-2-1 to win over the skin.
 *
 * The workaround is to artificially increase the specificity of the selectors
 * in this template so that we override the skin instead. We do this with the
 * :not() pseudo-class with a dummy ID selector that will never match anything.
 * Since TemplateStyles automatically get scoped to .mw-parser-text they have
 * an inherent extra class. Adding a :not() with a dummy ID selector should
 * therefore produce a specificity of 1-2-0 and win over the skin.
 *
 * That's not without drawbacks because there's a reason the skin does what it 
 * does on mobile. But we can't disable all font sizing on mobile either.
 *
 */
:not(#wst-workaround).wst-xx-smaller {
	font-size:58%;
}
:not(#wst-workaround).wst-x-smaller {
	font-size:69%;
}
:not(#wst-workaround).wst-smaller {
	font-size:83%;
}
:not(#wst-workaround).wst-fine {
	line-height:1.4;
	font-size:92%;
}
:not(#wst-workaround).wst-m-larger {
	font-size:110%;
}
:not(#wst-workaround).wst-larger {
	font-size:120%;
}
:not(#wst-workaround).wst-x-larger {
	font-size:144%;
}
:not(#wst-workaround).wst-xx-larger {
	font-size:182%;
}
:not(#wst-workaround).wst-xxx-larger {
	font-size:207%;
}
:not(#wst-workaround).wst-xxxx-larger {
	font-size:249%;
}

.wst-size-block {
	line-height:1.4;
}

/*
 * NOTE: :not() works around interference from the skin on mobile.
 *
 * All size classes get overridden on mobile by a high-specificity selector on
 * the p element. This means font size templates do not really work on mobile
 * and p-wrapping can lead to really inconsistent results. We need to exceed a
 * specificity of 0-2-1 to win over the skin.
 *
 * The workaround is to artificially increase the specificity of the selectors
 * in this template so that we override the skin instead. We do this with the
 * :not() pseudo-class with a dummy ID selector that will never match anything.
 * Since TemplateStyles automatically get scoped to .mw-parser-text they have
 * an inherent extra class. Adding a :not() with a dummy ID selector should
 * therefore produce a specificity of 1-2-0 and win over the skin.
 *
 * That's not without drawbacks because there's a reason the skin does what it 
 * does on mobile. But we can't disable all block font sizing on mobile either.
