 * We also need to force p-wrapped paragraphs to inherit font size, otherwuse
 * the direct styling in the skin will ignore the style applied by targetting
 * the parent element.
 *
 */
 /* Inside a size block, all p elements should inherit font size. */
 .wst-size-block p {
 	font-size: inherit;
 }

